/* FiredBunny brand: logo mark, wordmark, brand art, bunny voice helpers. Loaded right after core.js. */
(function () {
  'use strict';
  const SML = window.SML;

  SML.brandName = 'FiredBunny';
  /* Neon outline bunny (owner-supplied PNG, transparent background), 1200×800 WebP with alpha. */
  SML.brandArt = 'data:image/webp;base64,';
  /* Crisp flat logo (owner-supplied, Oct 22 2026), cropped to 5:4, 1000×800. Used where the art is shown large. */
  SML.brandLogo = 'data:image/webp;base64,';

  /* The bunny mark: white head with orange inner ears, orange sunglasses, on a dark tile with a flame-orange rim. */
  SML.bunnyMark = function (size, cls) {
    const s = size || 30;
    return `<svg class="fb-mark${cls ? ' ' + cls : ''}" width="${s}" height="${s}" viewBox="0 0 32 32" aria-hidden="true">
      <rect x="0.75" y="0.75" width="30.5" height="30.5" rx="7" style="fill:var(--bg);stroke:var(--flame)" stroke-width="1.5"/>
      <g transform="rotate(-14 11 10)"><ellipse cx="11" cy="9.6" rx="2.9" ry="7" style="fill:var(--ink)"/><ellipse cx="11" cy="10.2" rx="1.5" ry="5.1" style="fill:var(--flame)"/></g>
      <g transform="rotate(16 20.5 9.6)"><ellipse cx="20.5" cy="9.2" rx="2.9" ry="7" style="fill:var(--ink)"/><ellipse cx="20.5" cy="9.8" rx="1.5" ry="5.1" style="fill:var(--flame)"/></g>
      <ellipse cx="16" cy="20.6" rx="8.6" ry="7.2" style="fill:var(--ink)"/>
      <path d="M8.9 18.4h6.1l-.6 2.6a2.3 2.3 0 0 1-2.2 1.7h-.6a2.3 2.3 0 0 1-2.2-1.7zM17 18.4h6.1l-.5 2.6a2.3 2.3 0 0 1-2.2 1.7h-.6a2.3 2.3 0 0 1-2.2-1.7z" style="fill:var(--flame)"/>
      <path d="M15 19h2" stroke-width="1.1" style="stroke:var(--flame)"/>
      <path d="M15.2 23.6h1.6l-.8 1z" style="fill:var(--flame)"/>
      <path d="M14.4 25.4q1.6 1.2 3.2 0" fill="none" stroke-width=".9" stroke-linecap="round" style="stroke:var(--bg)"/>
    </svg>`;
  };
  /* A small flame, used on the wordmark and as a bullet of personality. */
  SML.flame = (size) => `<svg class="fb-flame" width="${size || 12}" height="${size || 12}" viewBox="0 0 24 24" aria-hidden="true"><path d="M12.6 2c.9 3.7 5.9 5.6 5.9 11a6.5 6.5 0 0 1-13 0c0-3.2 2-4.7 3.1-6.6.9 2 2 2.6 3 2.6-.2-2.3-.9-4.4 1-7z" style="fill:var(--flame)"/><path d="M12 13c.6 1.7 2.6 2.3 2.6 4.4a2.6 2.6 0 0 1-5.2 0c0-1.3.9-2 1.5-2.8.3.7.7 1 1.1 1z" style="fill:var(--gold)"/></svg>`;
  SML.wordmark = () => `<span class="fb-wm" aria-label="FiredBunny"><span class="fb-wm-f">Fired</span><span class="fb-wm-b">Bunny</span></span>`;

  /* Bunny voice: a short aside with the bunny head. */
  SML.bunnyTip = (html, label) => (SML.account && SML.account.get().prefs && SML.account.get().prefs.showTips === false) ? '' : `<div class="fb-tip">${SML.bunnyMark(28)}<div><p class="fb-tip-h">${label || 'Bunny tip'}</p><p>${html}</p></div></div>`;
  SML.hop = (msg) => { if (SML.toast) SML.toast(msg || 'Hop hop. Saved.'); };

  SML.css(`
    :root{--flame:#ff6224;--gold:#ffb52e;--flame-t:color-mix(in srgb,var(--flame) 14%,var(--surface))}
    .fb-mark{display:block;flex:0 0 auto;filter:drop-shadow(0 0 6px color-mix(in srgb,var(--flame) 45%,transparent))}
    .fb-flame{display:inline-block;vertical-align:-1px}
    .fb-wm{font-family:var(--sans);font-weight:700;font-style:italic;font-synthesis:style;letter-spacing:-.02em;line-height:1;white-space:nowrap}
    .fb-wm-f{color:var(--gold);text-shadow:0 0 14px color-mix(in srgb,var(--gold) 35%,transparent)}
    .fb-wm-b{color:var(--ink);text-shadow:0 0 14px color-mix(in srgb,var(--ink) 18%,transparent)}
    .fb-tip{display:flex;gap:12px;align-items:flex-start;background:color-mix(in srgb,var(--flame) 7%,var(--surface));border:1px solid color-mix(in srgb,var(--flame) 30%,var(--line));border-radius:var(--r);padding:14px 16px}
    .fb-tip p{font-size:14.5px;line-height:1.55;color:color-mix(in srgb,var(--ink) 88%,transparent)}
    .fb-tip .fb-tip-h{font:600 11px var(--mono);letter-spacing:.18em;text-transform:uppercase;color:var(--flame);margin-bottom:4px}
    .fb-art{display:block;width:100%;height:auto;border-radius:var(--r);background:#000}
    .fb-glow{text-shadow:0 0 18px color-mix(in srgb,var(--flame) 45%,transparent)}
  `);
})();
